-- READ ONLY after 033; no selection or save RPC is invoked.
with expected(signature,body_md5) as(values ('public.prepare_whatsapp_event_selection(uuid,uuid,jsonb,jsonb,jsonb,uuid[])','181a4dc82380ade757882aff76a5d965'),('public.receive_whatsapp_event_selection(text,text,text,text,timestamp with time zone,uuid,uuid,uuid,text,text)','016f818b81b542f667c2beaf88373665'))
select e.signature check_name,case when p.oid is not null and not p.prosecdef and p.proconfig @> ARRAY['search_path=""']::text[] and md5(btrim(replace(p.prosrc,chr(13),''),chr(32)||chr(9)||chr(10)))=e.body_md5 and has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE') then 'PASS' else 'FAIL' end status,md5(btrim(replace(p.prosrc,chr(13),''),chr(32)||chr(9)||chr(10))) actual_md5 from expected e left join pg_proc p on p.oid=to_regprocedure(e.signature) order by 1;
